records.content:
{
      drive: "การได้เป็นคนแรกที่ไปถึง และได้รู้ว่าตัวเองยังไม่จมอยู่กับที่",
      whisper: "'ถ้าไม่เริ่มตอนนี้ จะไม่มีวันได้เริ่ม'",
      fear: "การกลายเป็นคนธรรมดาที่ไม่มีใครจดจำ",
      need: "พื้นที่ให้ลองผิดลองถูกโดยไม่มีใครตัดสิน และต้องการคนที่เชื่อก่อนเห็นหลักฐาน",
      when: "ตอนที่ทุกอย่างกำลังนิ่ง และตอนที่เห็นคนอื่นเริ่มก่อนคุณ"
    }

/* ASC_FACE.1 */
{
      impression: "คนกล้าและสดใหม่ เหมือนเป็นคนที่พร้อมพาทุกคนไปที่ใหม่เสมอ",
      magnet: "ความกล้า และการที่คุณพูดแล้วทำจริงทันที",
      misread: "คุณไม่ค่อยแคร์รายละเอียดหรือไม่สนใจความรู้สึกคนอื่น",
      role: "คนนำทางและคนเปิดประตูให้ทีม",
      meeting: "เป็นฝ่ายเปิดบทสนทนาก่อน และมักชวนคุยเรื่องสิ่งที่กำลังจะทำ"
    }

{
      drive: "การเข้าใจทุกอย่างให้ครบก่อนขยับ และได้รู้ว่าตัวเองเห็นสิ่งที่คนอื่นมองข้าม",
      whisper: "'เดี๋ยวก่อน ยังมีอะไรที่เรายังไม่รู้'",
      fear: "การตัดสินใจผิดต่อหน้าคนอื่น และถูกมองว่าไม่ฉลาดพอ",
      need: "เวลาคิดทบทวนอย่างแท้จริง และต้องการคนที่ถามก่อนสรุปแทนคุณ",
      when: "ตอนที่ถูกกดดันให้ตอบทันที และตอนที่ทุกคนในวงเห็นตรงกันแต่คุณยังคาใจ"
    }

/* ASC_FACE.2 */
{
      impression: "คนเงียบแต่ลึก น่าคุยด้วย และเหมือนเป็นคนที่เข้าใจอะไรหลายอย่าง",
      magnet: "การรับฟังอย่างตั้งใจ และการจำรายละเอียดของคนอื่นได้แม่น",
      misread: "คุณไม่มีความเห็น หรือคิดว่าคุณไม่กล้าพูดต่อหน้าคนเยอะ",
      role: "ที่ปรึกษาและคนกลางที่ทุกฝ่ายยอมรับ",
      meeting: "ยังไม่พูดมาก แต่จะถามคำถามที่ทำให้เขาเล่าเรื่องตัวเองออกมา"
    }

{
      drive: "การได้ขยับและเห็นผลลัพธ์เร็ว ได้รู้ว่าตัวเองยังมีพลัง",
      whisper: "'เร็วเข้า ยังช้าไป'",
      fear: "การหยุดอยู่กับที่และถูกมองว่าไม่เอาไหน",
      need: "เป้าหมายที่ชัดและจับต้องได้ รวมถึงคนที่ตามจังหวะคุณทันในเรื่องใหญ่",
      when: "ตอนที่ต้องรอนาน และตอนที่เห็นความล่าช้าของคนอื่น"
    }

/* ASC_FACE.3 */
{
      impression: "คนมีไฟและพลังงานสูง ดูเป็นคนที่ทำอะไรแล้วสำเร็จบ่อย",
      magnet: "ความมั่นใจและรอยยิ้มที่ทำให้คนรู้สึกว่ามีโอกาส",
      misread: "คุณไม่ต้องพัก หรือคิดว่าคุณรับมือได้ทุกอย่างคนเดียว",
      role: "คนขับเคลื่อนและคนที่ถูกขอให้ปิดงานยาก",
      meeting: "เข้าหาแบบตรงไปตรงมา และมักชวนกันไปทำอะไรสักอย่างทันที"
    }

{
      drive: "การได้ทำให้ถูกต้องและปลอดภัย ได้รู้ว่าของที่คุณดูแลจะไม่พัง",
      whisper: "'ถ้าพลาดแล้วใครจะรับผิดชอบ'",
      fear: "การถูกตำหนิจากความผิดพลาดที่ควบคุมไม่ได้",
      need: "ข้อมูลที่ครบและเวลาที่พอ และต้องการคนที่กล้าเบรกคุณอย่างสุภาพ",
      when: "ก่อนการตัดสินใจครั้งใหญ่ และตอนที่คนอื่นเร่งให้คุณข้ามขั้นตอน"
    }

/* ASC_FACE.4 */
{
      impression: "คนสุขุม น่าเชื่อถือ และดูเหมือนคนที่ตรวจสอบทุกอย่างแล้ว",
      magnet: "ความจริงจังและคำพูดที่ไว้ใจได้ เพราะคุณไม่พูดเกินจริง",
      misread: "คุณเย็นชา เห็นใจคนอื่นยาก หรือไม่ค่อยเปิดรับแนวคิดใหม่",
      role: "คนคุมมาตรฐานและคนที่ทุกคนรอไฟเขียว",
      meeting: "กะและซักถามอย่างสุภาพ แล้วตอบรับช้าแต่ชัด"
    }

{
      drive: "การได้อยู่กับสิ่งที่มีความหมายระยะยาว ได้รู้ว่าตัวเองกำลังสะสมอะไรบางอย่าง",
      whisper: "'ยังไม่พร้อม เก็บอีกหน่อย'",
      fear: "การถูกมองทะลุและถูกตัดสินในสิ่งที่ยังไม่สมบูรณ์",
      need: "พื้นที่ส่วนตัวที่ไม่มีใครรบกวน และต้องการคนที่รอโดยไม่กดดัน",
      when: "ตอนที่ถูกขอให้เปิดเผยของที่ยังไม่เสร็จ และตอนที่ต้องเข้าสังคมติดกันหลายวัน"
    }

/* ASC_FACE.5 */
{
      impression: "คนนิ่ง ลึก และดูเหมือนมีเรื่องราวที่ทำให้มองคนออกมากกว่าวัย",
      magnet: "ความไม่เร่งรีบ และความสบายที่ทำให้คนอยากอยู่ข้าง ๆ เงียบ ๆ ด้วย",
      misread: "คุณไม่สนใจสังคม หรือคิดว่าคุณห่างเหินไม่แคร์ใคร",
      role: "ผู้เชี่ยวชาญและที่พักใจให้คนที่ไม่มีใครฟัง",
      meeting: "สังเกตก่อน แล้วค่อย ๆ เปิดเรื่องใกล้ตัวมากขึ้นตามความไว้ใจ"
    }

{
      drive: "การได้เรียนรู้สิ่งใหม่และได้ปรับตัว ได้รู้ว่าตัวเองยังไม่ตันอยู่กับทางเดิม",
      whisper: "'มันต้องมีทางที่ดีกว่านี้'",
      fear: "การติดอยู่ในสถานการณ์ที่ขยับไม่ได้",
      need: "ทางเลือกและอิสระในการปรับแผน และต้องการคนที่ยอมรับเมื่อคุณเปลี่ยนใจเพราะมีเหตุผล",
      when: "ตอนที่งานเริ่มซ้ำเดิม และตอนที่เห็นว่าวิธีเดิมไปไม่ได้แล้ว"
    }

/* ASC_FACE.6 */
{
      impression: "คนทันสมัย ปรับตัวเก่ง และดูเข้ากับทุกวงได้ทันที",
      magnet: "ความกระตือรือร้นในการเรียนรู้ และการทำให้คนรู้สึกว่าเขาสำคัญพอที่คุณจะเปลี่ยนตาม",
      misread: "คุณไม่จริงจัง หรือคิดว่าคุณไม่ยึดติดกับใครและอะไร",
      role: "คนเชื่อมวงและคนที่ทุกคนเรียกตอนต้องเริ่มสิ่งใหม่",
      meeting: "สร้างความคุ้นเคยเร็วด้วยการหาจุดร่วม และลองหาสิ่งที่เชิญไปทำด้วยกัน"
    }

{
      drive: "การได้แก้ที่ต้นเหตุและได้รู้ว่าตัวเองไม่ทิ้งปัญหาค้างไว้",
      whisper: "'เรื่องนี้ยังไม่จบ ต้องกลับไปดูอีกครั้ง'",
      fear: "การทำผิดซ้ำเรื่องเดิมที่เคยผิดมาแล้ว",
      need: "โอกาสได้สะสางให้ถึงราก และต้องการคนที่ยืนยันว่าเรื่องที่กลัวจะไม่เกิดซ้ำ",
      when: "ตอนที่เรื่องเดิมมีสัญญาณกลับมา และตอนที่ต้องเริ่มของใหม่ทั้งที่ของเก่ายังค้าง"
    }

/* ASC_FACE.7 */
{
      impression: "คนจริงจัง มีหลักการ และดูเหมือนเก็บเรื่องในอดีตไว้เป็นบทเรียน",
      magnet: "ความจริงใจและความกล้าพูดเรื่องที่คนอื่นเลี่ยง",
      misread: "คุณยังติดอยู่กับเรื่องเก่า หรือคิดว่าคุณจดจำเรื่องไม่ดีไว้ตลอด",
      role: "คนสะสางและคนที่ทุกคนให้กู้สถานการณ์ที่พังไว้",
      meeting: "พูดตรงและถามเรื่องที่ผ่านมา เพราะเชื่อว่าลึกกว่าคือจริงใจกว่า"
    }

{
      drive: "การได้สร้างความมั่นคงให้คนที่รักและได้รู้ว่าตัวเองเป็นที่พึ่งได้",
      whisper: "'อย่าเพิ่งเปลี่ยน เดี๋ยวจะเสียของที่สร้างไว้'",
      fear: "การสูญเสียสิ่งที่สร้างไว้อย่างมั่นคง",
      need: "ความแน่นอนของคนและสถานการณ์ และต้องการคนที่ชวนให้ขยับอย่างมีแผน",
      when: "ตอนที่ถูกเสนอให้เปลี่ยนสิ่งสำคัญ และตอนที่เห็นคนอื่นเปลี่ยนแปลงเร็วจนน่ากังวล"
    }

/* ASC_FACE.8 */
{
      impression: "คนอบอุ่น น่าพึ่งพา และดูเหมือนเป็นคนที่อยู่ได้นานและไม่ทิ้งกัน",
      magnet: "ความสบายใจที่คนอื่นได้รับเมื่ออยู่ใกล้คุณ",
      misread: "คุณไม่ทะเยอทะยาน หรือคิดว่าคุณไม่ชอบการเปลี่ยนแปลงเลย",
      role: "คนให้กำลังใจและหลักยึดของกลุ่ม",
      meeting: "เปิดรับด้วยความจริงใจ ให้เวลากับเขา และค่อย ๆ สร้างความไว้ใจระยะยาว"
    }

{
      drive: "การได้ทำให้เรื่องที่ตันอยู่คลี่คลายและได้รู้ว่าตัวเองมีประโยชน์",
      whisper: "'ถ้าเราไม่ช่วย เรื่องนี้จะไม่จบ'",
      fear: "การไม่มีใครต้องการ และการทิ้งคนที่กำลังเดือดร้อน",
      need: "พื้นที่ให้ตัวเองได้พักและถูกดูแลด้วย และต้องการคำยืนยันว่าคุณมีค่าแม้ไม่ได้รับใช้ใคร",
      when: "ตอนที่เห็นคนอื่นทุกข์ และตอนที่คุณเหนื่อยจนไม่มีอะไรเหลือให้ใคร"
    }

/* ASC_FACE.9 */
{
      impression: "คนเปิดกว้าง พูดแล้วสบายใจ และดูเหมือนเข้าใจภาพรวมก่อนคนอื่น",
      magnet: "ความโปร่งใจและคำพูดที่ทำให้เรื่องยุ่ง ๆ กลายเป็นเรื่องที่จัดการได้",
      misread: "คุณไม่มีความทุกข์ หรือคิดว่าคุณพร้อมช่วยเสมอไม่ว่าเวลาใด",
      role: "คนช่วยให้เดินหน้าต่อได้และพื้นที่ปลอดภัยของทุกคน",
      meeting: "ทำให้เขารู้สึกว่าถูกเข้าใจตั้งแต่ไม่กี่นาทีแรก และมักถูกรู้สึกว่าคุยได้ทุกเรื่อง"
    }

